#!/usr/bin/env julia
# RxInfer.jl Bayes-net inference — generated by gnn.rxinfer_bridge (GNN).
# GraphSpec format: dafjev.bayesnet/1 (pinned cross-repo contract with daf-jev).
#
# Jev integration points (upstream / within / downstream; full story in
# the module docstring of src/gnn/rxinfer_bridge.py and
# examples/rxinfer/README.md):
#   upstream   — CPTs and structure produced by daf-jev elicitation
#                (propose_structure + elicit_cpts), exchanged as this
#                GraphSpec JSON
#   within     — RESERVED: the optional GraphSpec "jev_factors" field
#                carries Jev-derived factors for future use; this script
#                ignores it (absent in this input)
#   downstream — posteriors printed below; --out FILE writes a
#                posteriors sidecar JSON for re-asking daf-jev
#                (see examples/rxinfer/README.md)
#
# Usage:
#   julia --project=. <script>.jl <graphspec.json> [--evidence key=state ...] [--out FILE] [--learn]
#
# Deterministic: identical GraphSpec input produces identical script text.

using RxInfer
using JSON

const ASIA_MODEL_VARS = [:asia, :smoke, :tub, :lung, :bronc, :either, :dysp, :xray]
const ASIA_MODEL_VARS_SET = Set(ASIA_MODEL_VARS)
const CHILD_PARENTS = Dict{Symbol,Vector{Symbol}}(
    :asia => Symbol[],
    :smoke => Symbol[],
    :tub => Symbol[:asia],
    :lung => Symbol[:smoke],
    :bronc => Symbol[:smoke],
    :either => Symbol[:lung, :tub],
    :dysp => Symbol[:either, :bronc],
    :xray => Symbol[:either],
)
const EYE_asia = [Float64(i == j) for i in 1:2, j in 1:2]
const EYE_smoke = [Float64(i == j) for i in 1:2, j in 1:2]
const EYE_tub = [Float64(i == j) for i in 1:2, j in 1:2]
const EYE_lung = [Float64(i == j) for i in 1:2, j in 1:2]
const EYE_bronc = [Float64(i == j) for i in 1:2, j in 1:2]
const EYE_either = [Float64(i == j) for i in 1:2, j in 1:2]
const EYE_dysp = [Float64(i == j) for i in 1:2, j in 1:2]
const EYE_xray = [Float64(i == j) for i in 1:2, j in 1:2]
const RAW_TO_IDENT = Dict{Symbol,Symbol}(:asia => :asia, :bronc => :bronc, :dysp => :dysp, :either => :either, :lung => :lung, :smoke => :smoke, :tub => :tub, :xray => :xray)
const IDENT_TO_RAW = Dict{Symbol,Symbol}(v => k for (k, v) in RAW_TO_IDENT)
const LEARNING_ITERATIONS = 25
const LEARNING_PRIOR_SCALE = 10.0
const LEARNING_ALPHA_EPS = 1e-6

"""
    load_spec(path) -> (spec, states, tensors)

Load and validate a dafjev.bayesnet/1 GraphSpec JSON; return the parsed
spec, the states map (Symbol key -> vector of state labels), and the
CPT tensors (Symbol child -> Array{Float64} with dims (child, p1, p2, ...)).
"""
function load_spec(path::AbstractString)
    isfile(path) || error("GraphSpec file not found: $path")
    spec = JSON.parsefile(path)
    got = get(spec, "format", nothing)
    got == "dafjev.bayesnet/1" || error("GraphSpec format: expected \"dafjev.bayesnet/1\", got $got")
    states = Dict{Symbol,Vector{String}}()
    for var in get(spec, "variables", [])
        raw_key = Symbol(String(var["key"]))
        haskey(RAW_TO_IDENT, raw_key) || error("GraphSpec variables: unknown key $raw_key (not in the compiled model)")
        key = RAW_TO_IDENT[raw_key]
        haskey(states, key) && error("GraphSpec variables: duplicate key $key")
        sts = String.(var["states"])
        length(sts) >= 2 || error("GraphSpec variable $key: needs at least 2 states")
        states[key] = sts
    end
    for key in ASIA_MODEL_VARS
        haskey(states, key) || error("GraphSpec variables: model variable $key missing")
    end
    for key in sort!(collect(keys(states)); by=String)
        key in ASIA_MODEL_VARS_SET || error("GraphSpec variables: unknown key $key not in the compiled model")
    end
    cpts = get(spec, "cpts", nothing)
    cpts isa AbstractDict || error("GraphSpec cpts: must be an object keyed by child")
    tensors = Dict{Symbol,Any}()
    for child in ASIA_MODEL_VARS
        parents = CHILD_PARENTS[child]
        cpt = get(cpts, String(IDENT_TO_RAW[child]), nothing)
        cpt === nothing && error("GraphSpec cpts: missing CPT for $child")
        declared = Symbol.(String.(get(cpt, "parents", [])))
        Tuple(declared) == Tuple(parents) || error("GraphSpec cpts[$child]: parents must be $(parents), got $(declared)")
        rows = get(cpt, "rows", nothing)
        rows isa AbstractVector || error("GraphSpec cpts[$child]: rows must be a list")
        n_child = length(states[child])
        if isempty(parents)
            length(rows) == 1 || error("GraphSpec cpts[$child]: expected exactly 1 prior row")
            probs = Float64.(rows[1]["probabilities"])
            length(probs) == n_child || error("GraphSpec cpts[$child]: prior row must have $n_child probabilities")
            _check_row(child, probs)
            tensors[child] = probs
        else
            expected_rows = prod(length(states[p]) for p in parents)
            length(rows) == expected_rows || error("GraphSpec cpts[$child]: expected $expected_rows rows, got $(length(rows))")
            dims = vcat([n_child], [length(states[p]) for p in parents])
            T = zeros(Float64, dims...)
            for row in rows
                assignment = get(row, "assignment", nothing)
                assignment isa AbstractDict || error("GraphSpec cpts[$child]: row assignment must be an object")
                idx = Int[]
                for p in parents
                    label = String(assignment[String(p)])
                    i = findfirst(==(label), states[p])
                    i === nothing && error("GraphSpec cpts[$child]: unknown state $label for parent $p")
                    push!(idx, i)
                end
                probs = Float64.(row["probabilities"])
                length(probs) == n_child || error("GraphSpec cpts[$child]: row must have $n_child probabilities")
                _check_row(child, probs)
                T[:, idx...] = probs
            end
            tensors[child] = T
        end
    end
    return spec, states, tensors
end

function _check_row(child::Symbol, probs::AbstractVector{Float64})
    for p in probs
        isfinite(p) && p >= 0.0 || error("GraphSpec cpts[$child]: probability $p is not finite and non-negative")
    end
    abs(sum(probs) - 1.0) <= 1e-6 || error("GraphSpec cpts[$child]: probabilities sum to $(sum(probs)), expected 1.0 within 1e-6")
    return nothing
end

@model function asia_model(p_asia, p_smoke, A_tub, A_lung, A_bronc, A_either, A_dysp, A_xray, e_asia, e_smoke, e_tub, e_lung, e_bronc, e_either, e_dysp, e_xray)
    asia ~ Categorical(p_asia)
    smoke ~ Categorical(p_smoke)
    tub ~ DiscreteTransition(asia, A_tub)
    lung ~ DiscreteTransition(smoke, A_lung)
    bronc ~ DiscreteTransition(smoke, A_bronc)
    either ~ DiscreteTransition(lung, A_either, tub)
    dysp ~ DiscreteTransition(either, A_dysp, bronc)
    xray ~ DiscreteTransition(either, A_xray)
    e_asia ~ DiscreteTransition(asia, EYE_asia)
    e_smoke ~ DiscreteTransition(smoke, EYE_smoke)
    e_tub ~ DiscreteTransition(tub, EYE_tub)
    e_lung ~ DiscreteTransition(lung, EYE_lung)
    e_bronc ~ DiscreteTransition(bronc, EYE_bronc)
    e_either ~ DiscreteTransition(either, EYE_either)
    e_dysp ~ DiscreteTransition(dysp, EYE_dysp)
    e_xray ~ DiscreteTransition(xray, EYE_xray)
end

# --- Learning variant (Dirichlet prior placeholders for CPT learning) ---
# Replace fixed data-arg probabilities with latent Dirichlet priors so
# RxInfer can learn the CPTs from evidence (pass --learn). Priors use a
# plain Dirichlet; parented CPTs use DirichletCollection (independent
# Dirichlets along the FIRST dimension, matching A[child, p1, p2, ...]).
@model function asia_model_learning(alpha_p_asia, alpha_p_smoke, alpha_A_tub, alpha_A_lung, alpha_A_bronc, alpha_A_either, alpha_A_dysp, alpha_A_xray, e_asia, e_smoke, e_tub, e_lung, e_bronc, e_either, e_dysp, e_xray)
    p_asia ~ Dirichlet(alpha_p_asia)
    asia ~ Categorical(p_asia)
    p_smoke ~ Dirichlet(alpha_p_smoke)
    smoke ~ Categorical(p_smoke)
    A_tub ~ DirichletCollection(alpha_A_tub)
    tub ~ DiscreteTransition(asia, A_tub)
    A_lung ~ DirichletCollection(alpha_A_lung)
    lung ~ DiscreteTransition(smoke, A_lung)
    A_bronc ~ DirichletCollection(alpha_A_bronc)
    bronc ~ DiscreteTransition(smoke, A_bronc)
    A_either ~ DirichletCollection(alpha_A_either)
    either ~ DiscreteTransition(lung, A_either, tub)
    A_dysp ~ DirichletCollection(alpha_A_dysp)
    dysp ~ DiscreteTransition(either, A_dysp, bronc)
    A_xray ~ DirichletCollection(alpha_A_xray)
    xray ~ DiscreteTransition(either, A_xray)
    e_asia ~ DiscreteTransition(asia, EYE_asia)
    e_smoke ~ DiscreteTransition(smoke, EYE_smoke)
    e_tub ~ DiscreteTransition(tub, EYE_tub)
    e_lung ~ DiscreteTransition(lung, EYE_lung)
    e_bronc ~ DiscreteTransition(bronc, EYE_bronc)
    e_either ~ DiscreteTransition(either, EYE_either)
    e_dysp ~ DiscreteTransition(dysp, EYE_dysp)
    e_xray ~ DiscreteTransition(xray, EYE_xray)
end

@constraints function asia_model_learning_constraints()
    q(tub, A_tub) = q(tub)q(A_tub)
    q(lung, A_lung) = q(lung)q(A_lung)
    q(bronc, A_bronc) = q(bronc)q(A_bronc)
    q(either, A_either) = q(either)q(A_either)
    q(dysp, A_dysp) = q(dysp)q(A_dysp)
    q(xray, A_xray) = q(xray)q(A_xray)
end

@initialization function asia_model_learning_init(alpha_A_tub, alpha_A_lung, alpha_A_bronc, alpha_A_either, alpha_A_dysp, alpha_A_xray, uniform_asia, uniform_smoke, uniform_tub, uniform_lung, uniform_bronc, uniform_either, uniform_dysp, uniform_xray)
    q(A_tub) = DirichletCollection(alpha_A_tub)
    q(A_lung) = DirichletCollection(alpha_A_lung)
    q(A_bronc) = DirichletCollection(alpha_A_bronc)
    q(A_either) = DirichletCollection(alpha_A_either)
    q(A_dysp) = DirichletCollection(alpha_A_dysp)
    q(A_xray) = DirichletCollection(alpha_A_xray)
    q(asia) = Categorical(uniform_asia)
    q(smoke) = Categorical(uniform_smoke)
    q(tub) = Categorical(uniform_tub)
    q(lung) = Categorical(uniform_lung)
    q(bronc) = Categorical(uniform_bronc)
    q(either) = Categorical(uniform_either)
    q(dysp) = Categorical(uniform_dysp)
    q(xray) = Categorical(uniform_xray)
end

@initialization function asia_model_init()
    q(asia) = Categorical(fill(1.0 / 2, 2))
    q(e_asia) = Categorical(fill(1.0 / 2, 2))
    q(smoke) = Categorical(fill(1.0 / 2, 2))
    q(e_smoke) = Categorical(fill(1.0 / 2, 2))
    q(tub) = Categorical(fill(1.0 / 2, 2))
    q(e_tub) = Categorical(fill(1.0 / 2, 2))
    q(lung) = Categorical(fill(1.0 / 2, 2))
    q(e_lung) = Categorical(fill(1.0 / 2, 2))
    q(bronc) = Categorical(fill(1.0 / 2, 2))
    q(e_bronc) = Categorical(fill(1.0 / 2, 2))
    q(either) = Categorical(fill(1.0 / 2, 2))
    q(e_either) = Categorical(fill(1.0 / 2, 2))
    q(dysp) = Categorical(fill(1.0 / 2, 2))
    q(e_dysp) = Categorical(fill(1.0 / 2, 2))
    q(xray) = Categorical(fill(1.0 / 2, 2))
    q(e_xray) = Categorical(fill(1.0 / 2, 2))
end

function parse_args(argv::Vector{String})
    isempty(argv) && error("usage: julia <script>.jl <graphspec.json> [--evidence key=state ...] [--out FILE] [--learn]")
    spec_path = argv[1]
    evidence_labels = Dict{Symbol,String}()
    out_path = nothing
    learn = false
    i = 2
    while i <= length(argv)
        arg = argv[i]
        if arg == "--evidence"
            i + 1 <= length(argv) || error("--evidence requires a key=state value")
            kv = split(argv[i+1], "="; limit=2)
            length(kv) == 2 || error("--evidence expects key=state, got $(argv[i+1])")
            key = Symbol(strip(kv[1]))
            haskey(evidence_labels, key) && error("duplicate evidence key: $key")
            evidence_labels[key] = String(strip(kv[2]))
            i += 2
        elseif arg == "--out"
            i + 1 <= length(argv) || error("--out requires a path")
            out_path = argv[i+1]
            i += 2
        elseif arg == "--learn"
            learn = true
            i += 1
        else
            error("unknown argument: $arg")
        end
    end
    return spec_path, evidence_labels, out_path, learn
end

function resolve_evidence(evidence_labels, states)
    evidence = Dict{Symbol,Any}()
    for ident in ASIA_MODEL_VARS
        evidence[ident] = missing
    end
    for (key, label) in sort!(collect(evidence_labels); by=x->String(x[1]))
        haskey(RAW_TO_IDENT, key) || error("evidence key not in model: $key")
        ident = RAW_TO_IDENT[key]
        options = get(states, ident, nothing)
        options === nothing && error("evidence key not in model: $key")
        idx = findfirst(==(label), options)
        idx === nothing && error("evidence state not in states of $key: $label (states: $options)")
        onehot = zeros(Float64, length(options))
        onehot[idx] = 1.0
        evidence[ident] = onehot
    end
    return evidence
end

function main(argv::Vector{String})
    spec_path, evidence_labels, out_path, learn = parse_args(argv)
    spec, states, tensors = load_spec(spec_path)
    evidence = resolve_evidence(evidence_labels, states)
    if learn
        result = _run_learning(states, tensors, evidence)
    else
        result = _run_inference(states, tensors, evidence)
    end
    if out_path !== nothing
        _write_sidecar(result, states, evidence, out_path)
    end
    return 0
end

function _run_inference(states, tensors, evidence::Dict{Symbol,Any})
    predict = Dict{Symbol,Any}(Symbol(:e_, k) => KeepLast() for (k, v) in evidence if v === missing)
    result = infer(model = asia_model(p_asia = tensors[:asia], p_smoke = tensors[:smoke], A_tub = tensors[:tub], A_lung = tensors[:lung], A_bronc = tensors[:bronc], A_either = tensors[:either], A_dysp = tensors[:dysp], A_xray = tensors[:xray]), data = Dict{Symbol,Any}(Symbol(:e_, k) => v for (k, v) in evidence if v !== missing), predictvars = predict, initialization = asia_model_init())
    println("Observed evidence:")
    for key in ASIA_MODEL_VARS
        evidence[key] === missing && continue
        println("  $(key) = $(states[key][findfirst(==(1.0), evidence[key])])")
    end
    println("Posteriors (marginal P(key)):")
    for key in ASIA_MODEL_VARS
        evidence[key] !== missing && continue
        probs = result.posteriors[key].p
        rendered = join(["$(states[key][i])=$(round(probs[i]; digits=6))" for i in 1:length(probs)], "  ")
        println("  $(key): $(rendered)")
    end
    return result
end

function _run_learning(states, tensors, evidence::Dict{Symbol,Any})
    alphas = Dict{Symbol,Any}()
    for key in ASIA_MODEL_VARS
        alphas[key] = tensors[key] .* LEARNING_PRIOR_SCALE .+ LEARNING_ALPHA_EPS
    end
    result = infer(model = asia_model_learning(alpha_p_asia = alphas[:asia], alpha_p_smoke = alphas[:smoke], alpha_A_tub = alphas[:tub], alpha_A_lung = alphas[:lung], alpha_A_bronc = alphas[:bronc], alpha_A_either = alphas[:either], alpha_A_dysp = alphas[:dysp], alpha_A_xray = alphas[:xray]), data = Dict{Symbol,Any}(Symbol(:e_, k) => v for (k, v) in evidence), constraints = asia_model_learning_constraints(), initialization = asia_model_learning_init(alphas[:tub], alphas[:lung], alphas[:bronc], alphas[:either], alphas[:dysp], alphas[:xray], fill(1.0 / length(states[:asia]), length(states[:asia])), fill(1.0 / length(states[:smoke]), length(states[:smoke])), fill(1.0 / length(states[:tub]), length(states[:tub])), fill(1.0 / length(states[:lung]), length(states[:lung])), fill(1.0 / length(states[:bronc]), length(states[:bronc])), fill(1.0 / length(states[:either]), length(states[:either])), fill(1.0 / length(states[:dysp]), length(states[:dysp])), fill(1.0 / length(states[:xray]), length(states[:xray]))), iterations = LEARNING_ITERATIONS, free_energy = true)
    println("Learning inference completed (iterations = $(LEARNING_ITERATIONS)).")
    println("Final variational free energy: $(result.free_energy)")
    return result
end

function _write_sidecar(result, states, evidence::Dict{Symbol,Any}, out_path::AbstractString)
    doc = Dict{String,Any}()
    doc["format"] = "dafjev.bayesnet-posteriors/1"
    doc["evidence"] = Dict(String(k) => String(states[k][findfirst(==(1.0), v)]) for (k, v) in evidence if v !== missing)
    doc["posteriors"] = Dict{String,Any}()
    for key in ASIA_MODEL_VARS
        if evidence[key] !== missing
            onehot = evidence[key]
            doc["posteriors"][String(key)] = Dict(String(states[key][i]) => onehot[i] for i in 1:length(onehot))
        else
            probs = result.posteriors[key].p
            doc["posteriors"][String(key)] = Dict(String(states[key][i]) => probs[i] for i in 1:length(probs))
        end
    end
    open(out_path, "w") do io
        JSON.print(io, doc, 2)
    end
    println("Wrote posteriors sidecar: $out_path")
    return nothing
end

if abspath(PROGRAM_FILE) == @__FILE__
    exit(main(ARGS))
end
